'use strict';
(()=>{
 const canvas=document.querySelector('#portrait-canvas'),ctx=canvas.getContext('2d'),host=canvas.parentElement,img=new Image();
 const dots=document.createElement('canvas'),dctx=dots.getContext('2d'),source=document.createElement('canvas'),sctx=source.getContext('2d',{willReadFrequently:true});
 let width=320,height=430,hover=null,paused=matchMedia('(prefers-reduced-motion: reduce)').matches,time=0,last=0,ready=false;
 const button=document.querySelector('#motion');
 function resize(){width=Math.max(1,host.clientWidth);height=Math.max(1,host.clientHeight);canvas.width=width*2;canvas.height=height*2;ctx.setTransform(2,0,0,2,0,0);source.width=dots.width=Math.ceil(width*2);source.height=dots.height=Math.ceil(height*2);sctx.clearRect(0,0,source.width,source.height);const scale=Math.max(source.width/850,source.height/1120),w=850*scale,h=1120*scale;sctx.drawImage(img,160,0,850,1120,(source.width-w)/2,source.height-h,w,h);const pixels=sctx.getImageData(0,0,source.width,source.height).data;dctx.clearRect(0,0,dots.width,dots.height);dctx.fillStyle='#222629';for(let y=2;y<dots.height;y+=7)for(let x=2;x<dots.width;x+=7){const i=(y*dots.width+x)*4;if(pixels[i+3]<60)continue;const luminance=(pixels[i]*.2126+pixels[i+1]*.7152+pixels[i+2]*.0722)/255;const radius=(1-luminance)*3.1+.3;dctx.beginPath();dctx.arc(x,y,radius,0,Math.PI*2);dctx.fill();}dctx.globalCompositeOperation='destination-in';dctx.drawImage(source,0,0);dctx.globalCompositeOperation='source-over';draw();}
 function draw(){if(!ready)return;ctx.clearRect(0,0,width,height);const intro=paused?1:Math.min(time/3200,1);ctx.save();ctx.beginPath();ctx.rect(0,height*intro,width,height*(1-intro));ctx.clip();ctx.drawImage(dots,0,0,width,height);ctx.restore();ctx.save();ctx.beginPath();ctx.rect(0,0,width,height*intro);ctx.clip();ctx.drawImage(source,0,0,width,height);ctx.restore();if(!paused){const y=(time%6500)/6500*(height+65)-30;ctx.save();ctx.beginPath();ctx.rect(0,y-27,width,27);ctx.clip();ctx.clearRect(0,y-27,width,27);ctx.drawImage(dots,0,0,width,height);ctx.restore();ctx.strokeStyle='#b34320';ctx.lineWidth=.9;ctx.beginPath();ctx.moveTo(0,y);ctx.lineTo(width,y);ctx.stroke();if(y>8&&y<height-15){ctx.fillStyle='#ac3c17';ctx.font='8px monospace';ctx.fillText('VARREDURA',4,y+12);}}
 if(hover){const {x,y}=hover,r=38;ctx.save();ctx.beginPath();ctx.arc(x,y,r,0,Math.PI*2);ctx.clip();ctx.fillStyle='#f7f4ec';ctx.fillRect(x-r,y-r,r*2,r*2);const zoom=1.8;ctx.drawImage(dots,x-width/2*zoom-(x-width/2)*zoom,y-height/2*zoom-(y-height/2)*zoom,width*zoom,height*zoom);ctx.restore();ctx.strokeStyle='#292d2d';ctx.lineWidth=1;ctx.beginPath();ctx.arc(x,y,r,0,Math.PI*2);ctx.stroke();ctx.strokeStyle='#ad3c18';for(const [dx,dy] of [[-1,0],[1,0],[0,-1],[0,1]]){ctx.beginPath();ctx.moveTo(x+dx*r,y+dy*r);ctx.lineTo(x+dx*(r+6),y+dy*(r+6));ctx.stroke();}ctx.fillStyle='#ac3c17';ctx.font='8px monospace';ctx.fillText('DET. A',Math.min(width-39,x+r+8),Math.max(9,y-r));}}
 function frame(now){if(!last)last=now;if(!paused&&!document.hidden)time+=Math.min(now-last,60);last=now;draw();requestAnimationFrame(frame);}
 host.addEventListener('pointermove',e=>{if(e.pointerType==='touch')return;const r=canvas.getBoundingClientRect();hover={x:e.clientX-r.left,y:e.clientY-r.top};draw();});host.addEventListener('pointerleave',()=>{hover=null;draw();});
 function sync(){button.setAttribute('aria-pressed',String(paused));button.textContent=paused?'▷ Animar diagrama':'Ⅱ Pausar diagrama';document.querySelectorAll('.wires').forEach(s=>paused?s.pauseAnimations():s.unpauseAnimations());}
 button.addEventListener('click',()=>{paused=!paused;sync();draw();});matchMedia('(prefers-reduced-motion: reduce)').addEventListener('change',e=>{paused=e.matches;sync();});
 img.onload=()=>{ready=true;resize();new ResizeObserver(resize).observe(host);sync();requestAnimationFrame(frame);};img.src='assets/vinicius-transparent.png';
})();
